INSERT INTO lessons VALUES('P1B-U03-L1',1,'term-b-neighbourhoods-v1',1,'B',3,'铅笔在哪里','{"id":"P1B-U03-L1","unitId":"P1B-U03","grade":1,"term":"B","unitNumber":3,"unitLesson":1,"order":9,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":10,"title":"铅笔在哪里","conceptLabIds":["grammar.prepositions"],"releaseId":"term-b-neighbourhoods-v1","unitTitle":"我的教室","cards":[{"title":"铅笔在哪里","rule":"问一个物品在哪里，用Where is…? 回答可用It is in…表示在里面。in说容器内部，不是盒子表面。先看给出的文字情景，不用猜现实中物品的位置。","example":"Where is the pencil?","translation":"铅笔在哪里？"},{"title":"铅笔在哪里","rule":"问一个物品在哪里，用Where is…? 回答可用It is in…表示在里面。in说容器内部，不是盒子表面。先看给出的文字情景，不用猜现实中物品的位置。","example":"It is in the blue pencil case.","translation":"它在蓝色笔袋里。"},{"title":"铅笔在哪里","rule":"问一个物品在哪里，用Where is…? 回答可用It is in…表示在里面。in说容器内部，不是盒子表面。先看给出的文字情景，不用猜现实中物品的位置。","example":"The eraser is in the small box.","translation":"橡皮在小盒子里。"}],"vocabulary":[{"word":"where","meaning":"在哪里"},{"word":"pencil case","meaning":"笔袋"},{"word":"in","meaning":"在……里面"},{"word":"eraser","meaning":"橡皮"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.prepositions","sentence.wh"],"itemCount":9}');
INSERT INTO lessons VALUES('P1B-U03-L2',1,'term-b-neighbourhoods-v1',1,'B',3,'书在桌面上','{"id":"P1B-U03-L2","unitId":"P1B-U03","grade":1,"term":"B","unitNumber":3,"unitLesson":2,"order":10,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":10,"title":"书在桌面上","conceptLabIds":["grammar.prepositions"],"releaseId":"term-b-neighbourhoods-v1","unitTitle":"我的教室","cards":[{"title":"书在桌面上","rule":"on表示在表面上，通常有接触。The book is on the desk说书放在桌面上；in the desk说在桌子内部的空间。位置由情景决定，不能只看物品名猜介词。","example":"The book is on the desk.","translation":"书在桌面上。"},{"title":"书在桌面上","rule":"on表示在表面上，通常有接触。The book is on the desk说书放在桌面上；in the desk说在桌子内部的空间。位置由情景决定，不能只看物品名猜介词。","example":"The cup is on the tray.","translation":"杯子在托盘上。"},{"title":"书在桌面上","rule":"on表示在表面上，通常有接触。The book is on the desk说书放在桌面上；in the desk说在桌子内部的空间。位置由情景决定，不能只看物品名猜介词。","example":"The picture is on the wall.","translation":"画在墙上。"}],"vocabulary":[{"word":"desk","meaning":"书桌"},{"word":"tray","meaning":"托盘"},{"word":"on","meaning":"在……上面"},{"word":"surface","meaning":"表面"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.prepositions","sentence.wh"],"itemCount":9}');
INSERT INTO lessons VALUES('P1B-U03-L3',1,'term-b-neighbourhoods-v1',1,'B',3,'找找下面的物品','{"id":"P1B-U03-L3","unitId":"P1B-U03","grade":1,"term":"B","unitNumber":3,"unitLesson":3,"order":11,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":10,"title":"找找下面的物品","conceptLabIds":["grammar.prepositions"],"releaseId":"term-b-neighbourhoods-v1","unitTitle":"我的教室","cards":[{"title":"找找下面的物品","rule":"under表示在某物下方，和on表面的关系不同。问Where is the…? 时，先找物品，再听清参照物。under不是所有中文“里面”的翻译。","example":"The ball is under the chair.","translation":"球在椅子下面。"},{"title":"找找下面的物品","rule":"under表示在某物下方，和on表面的关系不同。问Where is the…? 时，先找物品，再听清参照物。under不是所有中文“里面”的翻译。","example":"Where is the toy car?","translation":"玩具车在哪里？"},{"title":"找找下面的物品","rule":"under表示在某物下方，和on表面的关系不同。问Where is the…? 时，先找物品，再听清参照物。under不是所有中文“里面”的翻译。","example":"It is under the low table.","translation":"它在矮桌下面。"}],"vocabulary":[{"word":"under","meaning":"在……下面"},{"word":"chair","meaning":"椅子"},{"word":"table","meaning":"桌子"},{"word":"find","meaning":"找到"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.prepositions","sentence.wh"],"itemCount":9}');
INSERT INTO lessons VALUES('P1B-U03-L4',1,'term-b-neighbourhoods-v1',1,'B',3,'按位置整理教室','{"id":"P1B-U03-L4","unitId":"P1B-U03","grade":1,"term":"B","unitNumber":3,"unitLesson":4,"order":12,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":10,"title":"按位置整理教室","conceptLabIds":["grammar.prepositions"],"releaseId":"term-b-neighbourhoods-v1","unitTitle":"我的教室","cards":[{"title":"按位置整理教室","rule":"Put加物品，再加in / on / under说明放在哪里。Put the pen in the case是让人去放；The pen is in the case是在说现在的位置。两种句子用途不同。","example":"Put the cards in the basket.","translation":"把卡片放进篮子里。"},{"title":"按位置整理教室","rule":"Put加物品，再加in / on / under说明放在哪里。Put the pen in the case是让人去放；The pen is in the case是在说现在的位置。两种句子用途不同。","example":"Put the poster on the board.","translation":"把海报放到板上。"},{"title":"按位置整理教室","rule":"Put加物品，再加in / on / under说明放在哪里。Put the pen in the case是让人去放；The pen is in the case是在说现在的位置。两种句子用途不同。","example":"The basket is under the shelf.","translation":"篮子在架子下面。"}],"vocabulary":[{"word":"put","meaning":"放"},{"word":"basket","meaning":"篮子"},{"word":"board","meaning":"板"},{"word":"tidy","meaning":"整理"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.prepositions","sentence.wh"],"itemCount":9}');
INSERT INTO lessons VALUES('P2B-U03-L1',1,'term-b-neighbourhoods-v1',2,'B',3,'紧挨着的邻居','{"id":"P2B-U03-L1","unitId":"P2B-U03","grade":2,"term":"B","unitNumber":3,"unitLesson":1,"order":9,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":10,"title":"紧挨着的邻居","releaseId":"term-b-neighbourhoods-v1","unitTitle":"社区散步","cards":[{"title":"紧挨着的邻居","rule":"next to表示紧挨着，next和to一起使用。near只说在附近，范围较宽；紧挨着的地点也可以说near，不能把两个词的意思看成绝不重叠。","example":"The bakery is next to the bookshop.","translation":"面包店紧挨着书店。"},{"title":"紧挨着的邻居","rule":"next to表示紧挨着，next和to一起使用。near只说在附近，范围较宽；紧挨着的地点也可以说near，不能把两个词的意思看成绝不重叠。","example":"Where is the toy shop?","translation":"玩具店在哪里？"},{"title":"紧挨着的邻居","rule":"next to表示紧挨着，next和to一起使用。near只说在附近，范围较宽；紧挨着的地点也可以说near，不能把两个词的意思看成绝不重叠。","example":"It is next to the bank.","translation":"它紧挨着银行。"}],"vocabulary":[{"word":"bakery","meaning":"面包店"},{"word":"bookshop","meaning":"书店"},{"word":"next to","meaning":"紧挨着"},{"word":"bank","meaning":"银行"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.prepositions","sentence.wh","sentence.wh"],"itemCount":9}');
INSERT INTO lessons VALUES('P2B-U03-L2',1,'term-b-neighbourhoods-v1',2,'B',3,'附近不一定紧挨着','{"id":"P2B-U03-L2","unitId":"P2B-U03","grade":2,"term":"B","unitNumber":3,"unitLesson":2,"order":10,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":10,"title":"附近不一定紧挨着","releaseId":"term-b-neighbourhoods-v1","unitTitle":"社区散步","cards":[{"title":"附近不一定紧挨着","rule":"near表示附近，不必共用边界。说near the park时，near后直接接地点，不加to。图中没有距离信息时，不能凭near推断相邻店铺。","example":"The bus stop is near the park.","translation":"公交站在公园附近。"},{"title":"附近不一定紧挨着","rule":"near表示附近，不必共用边界。说near the park时，near后直接接地点，不加to。图中没有距离信息时，不能凭near推断相邻店铺。","example":"A cafe is near our school.","translation":"一间咖啡馆在学校附近。"},{"title":"附近不一定紧挨着","rule":"near表示附近，不必共用边界。说near the park时，near后直接接地点，不加to。图中没有距离信息时，不能凭near推断相邻店铺。","example":"Near does not mean right next door.","translation":"在附近不一定是紧挨着。"}],"vocabulary":[{"word":"near","meaning":"在……附近"},{"word":"bus stop","meaning":"公交站"},{"word":"park","meaning":"公园"},{"word":"clinic","meaning":"诊所"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.prepositions","sentence.wh","sentence.wh"],"itemCount":9}');
INSERT INTO lessons VALUES('P2B-U03-L3',1,'term-b-neighbourhoods-v1',2,'B',3,'用Where找到地方','{"id":"P2B-U03-L3","unitId":"P2B-U03","grade":2,"term":"B","unitNumber":3,"unitLesson":3,"order":11,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":10,"title":"用Where找到地方","releaseId":"term-b-neighbourhoods-v1","unitTitle":"社区散步","cards":[{"title":"用Where找到地方","rule":"问一个地点在哪里，用Where is the…? Where问位置；What问事物，When问时间。回答可直接说明地点关系，不把is再放到句尾。","example":"Where is the library?","translation":"图书馆在哪里？"},{"title":"用Where找到地方","rule":"问一个地点在哪里，用Where is the…? Where问位置；What问事物，When问时间。回答可直接说明地点关系，不把is再放到句尾。","example":"It is near the sports centre.","translation":"它在体育中心附近。"},{"title":"用Where找到地方","rule":"问一个地点在哪里，用Where is the…? Where问位置；What问事物，When问时间。回答可直接说明地点关系，不把is再放到句尾。","example":"Where is the post office?","translation":"邮局在哪里？"}],"vocabulary":[{"word":"library","meaning":"图书馆"},{"word":"post office","meaning":"邮局"},{"word":"sports centre","meaning":"体育中心"},{"word":"location","meaning":"位置"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.prepositions","sentence.wh","sentence.wh"],"itemCount":9}');
INSERT INTO lessons VALUES('P2B-U03-L4',1,'term-b-neighbourhoods-v1',2,'B',3,'读懂社区的小便条','{"id":"P2B-U03-L4","unitId":"P2B-U03","grade":2,"term":"B","unitNumber":3,"unitLesson":4,"order":12,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":10,"title":"读懂社区的小便条","releaseId":"term-b-neighbourhoods-v1","unitTitle":"社区散步","cards":[{"title":"读懂社区的小便条","rule":"读位置便条时先找地点名，再找next to或near。两个地点near并不能说明谁在左边或右边；文字没有给的信息，要说还不能确定。","example":"The school is near the river.","translation":"学校在河流附近。"},{"title":"读懂社区的小便条","rule":"读位置便条时先找地点名，再找next to或near。两个地点near并不能说明谁在左边或右边；文字没有给的信息，要说还不能确定。","example":"The cafe is next to the bakery.","translation":"咖啡馆紧挨着面包店。"},{"title":"读懂社区的小便条","rule":"读位置便条时先找地点名，再找next to或near。两个地点near并不能说明谁在左边或右边；文字没有给的信息，要说还不能确定。","example":"The note does not say which side.","translation":"便条没有说是哪一侧。"}],"vocabulary":[{"word":"note","meaning":"便条"},{"word":"river","meaning":"河流"},{"word":"side","meaning":"一侧"},{"word":"map","meaning":"地图"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.prepositions","sentence.wh","sentence.wh"],"itemCount":9}');
INSERT INTO lessons VALUES('P3B-U03-L1',1,'term-b-neighbourhoods-v1',3,'B',3,'公园里有什么','{"id":"P3B-U03-L1","unitId":"P3B-U03","grade":3,"term":"B","unitNumber":3,"unitLesson":1,"order":9,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":12,"title":"公园里有什么","releaseId":"term-b-neighbourhoods-v1","unitTitle":"去哪里玩","cards":[{"title":"公园里有什么","rule":"介绍一个地方有什么，用There is加单数或不可数名词，There are加复数名词。它们介绍存在的东西；不是所有中文“有”都用have。","example":"There is a pond in the park.","translation":"公园里有一个池塘。"},{"title":"公园里有什么","rule":"介绍一个地方有什么，用There is加单数或不可数名词，There are加复数名词。它们介绍存在的东西；不是所有中文“有”都用have。","example":"There are three benches by the pond.","translation":"池塘旁有三条长凳。"},{"title":"公园里有什么","rule":"介绍一个地方有什么，用There is加单数或不可数名词，There are加复数名词。它们介绍存在的东西；不是所有中文“有”都用have。","example":"There is some water in the pond.","translation":"池塘里有一些水。"}],"vocabulary":[{"word":"pond","meaning":"池塘"},{"word":"bench","meaning":"长凳"},{"word":"path","meaning":"小路"},{"word":"water","meaning":"水"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.there-be","grammar.prepositions","sentence.yes-no"],"itemCount":9}');
INSERT INTO lessons VALUES('P3B-U03-L2',1,'term-b-neighbourhoods-v1',3,'B',3,'地图上没有什么','{"id":"P3B-U03-L2","unitId":"P3B-U03","grade":3,"term":"B","unitNumber":3,"unitLesson":2,"order":10,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":12,"title":"地图上没有什么","releaseId":"term-b-neighbourhoods-v1","unitTitle":"去哪里玩","cards":[{"title":"地图上没有什么","rule":"There isn''t加单数，There aren''t加复数，表示某处没有。完整写法is not / are not也可以。按这张虚构地图回答，不推测真实公园的设施。","example":"There isn''t a cafe beside this lake.","translation":"这个湖旁没有咖啡馆。"},{"title":"地图上没有什么","rule":"There isn''t加单数，There aren''t加复数，表示某处没有。完整写法is not / are not也可以。按这张虚构地图回答，不推测真实公园的设施。","example":"There aren''t any boats on this lake.","translation":"这个湖上没有船。"},{"title":"地图上没有什么","rule":"There isn''t加单数，There aren''t加复数，表示某处没有。完整写法is not / are not也可以。按这张虚构地图回答，不推测真实公园的设施。","example":"There are not any signs here.","translation":"这里没有指示牌。"}],"vocabulary":[{"word":"boat","meaning":"船"},{"word":"sign","meaning":"指示牌"},{"word":"any","meaning":"一些（常用于否定或疑问）"},{"word":"lake","meaning":"湖"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.there-be","grammar.prepositions","sentence.yes-no"],"itemCount":9}');
INSERT INTO lessons VALUES('P3B-U03-L3',1,'term-b-neighbourhoods-v1',3,'B',3,'先问有没有','{"id":"P3B-U03-L3","unitId":"P3B-U03","grade":3,"term":"B","unitNumber":3,"unitLesson":3,"order":11,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":12,"title":"先问有没有","releaseId":"term-b-neighbourhoods-v1","unitTitle":"去哪里玩","cards":[{"title":"先问有没有","rule":"Is there加单数，Are there加复数。简短回答与问句对应：Yes, there is. / No, there aren''t. 先确认地图文字，再问具体位置。","example":"Is there a library near the square?","translation":"广场附近有图书馆吗？"},{"title":"先问有没有","rule":"Is there加单数，Are there加复数。简短回答与问句对应：Yes, there is. / No, there aren''t. 先确认地图文字，再问具体位置。","example":"Yes, there is.","translation":"是的，有。"},{"title":"先问有没有","rule":"Is there加单数，Are there加复数。简短回答与问句对应：Yes, there is. / No, there aren''t. 先确认地图文字，再问具体位置。","example":"Are there any buses at the stop?","translation":"站台有公交车吗？"}],"vocabulary":[{"word":"square","meaning":"广场"},{"word":"shelter","meaning":"遮雨棚"},{"word":"machine","meaning":"机器"},{"word":"check","meaning":"核对"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.there-be","grammar.prepositions","sentence.yes-no"],"itemCount":9}');
INSERT INTO lessons VALUES('P3B-U03-L4',1,'term-b-neighbourhoods-v1',3,'B',3,'把设施和位置一起说','{"id":"P3B-U03-L4","unitId":"P3B-U03","grade":3,"term":"B","unitNumber":3,"unitLesson":4,"order":12,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":12,"title":"把设施和位置一起说","releaseId":"term-b-neighbourhoods-v1","unitTitle":"去哪里玩","cards":[{"title":"把设施和位置一起说","rule":"There is / are加事物，再用位置短语说明在哪里。between A and B表示在A与B之间，near表示附近。看地图文字，不把未说明的距离或方向当事实。","example":"There is a kiosk between the cafe and the bank.","translation":"咖啡馆和银行之间有一个售货亭。"},{"title":"把设施和位置一起说","rule":"There is / are加事物，再用位置短语说明在哪里。between A and B表示在A与B之间，near表示附近。看地图文字，不把未说明的距离或方向当事实。","example":"There are two bins near the steps.","translation":"台阶附近有两个垃圾桶。"},{"title":"把设施和位置一起说","rule":"There is / are加事物，再用位置短语说明在哪里。between A and B表示在A与B之间，near表示附近。看地图文字，不把未说明的距离或方向当事实。","example":"The bridge is beside the tower.","translation":"桥在塔旁。"}],"vocabulary":[{"word":"between","meaning":"在……之间"},{"word":"beside","meaning":"在……旁边"},{"word":"bin","meaning":"垃圾桶"},{"word":"tower","meaning":"塔"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.there-be","grammar.prepositions","sentence.yes-no"],"itemCount":9}');
INSERT INTO lessons VALUES('P4B-U03-L1',1,'term-b-neighbourhoods-v1',4,'B',3,'左转和右转','{"id":"P4B-U03-L1","unitId":"P4B-U03","grade":4,"term":"B","unitNumber":3,"unitLesson":1,"order":9,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":12,"title":"左转和右转","releaseId":"term-b-neighbourhoods-v1","unitTitle":"问路小帮手","cards":[{"title":"左转和右转","rule":"指路可用Turn left / Turn right。祈使句从动词原形开始，不写Turns，也不必加You。左右以行路者面向前进方向为准，本课文字会明确方向。","example":"Turn left at the bakery.","translation":"在面包店处左转。"},{"title":"左转和右转","rule":"指路可用Turn left / Turn right。祈使句从动词原形开始，不写Turns，也不必加You。左右以行路者面向前进方向为准，本课文字会明确方向。","example":"Turn right at the second corner.","translation":"在第二个拐角处右转。"},{"title":"左转和右转","rule":"指路可用Turn left / Turn right。祈使句从动词原形开始，不写Turns，也不必加You。左右以行路者面向前进方向为准，本课文字会明确方向。","example":"Go straight along this road.","translation":"沿这条路直走。"}],"vocabulary":[{"word":"left","meaning":"左边"},{"word":"right","meaning":"右边"},{"word":"corner","meaning":"拐角"},{"word":"straight","meaning":"直地；笔直地"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.wh","grammar.prepositions","sentence.patterns.requests"],"itemCount":9}');
INSERT INTO lessons VALUES('P4B-U03-L2',1,'term-b-neighbourhoods-v1',4,'B',3,'沿着走和经过','{"id":"P4B-U03-L2","unitId":"P4B-U03","grade":4,"term":"B","unitNumber":3,"unitLesson":2,"order":10,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":12,"title":"沿着走和经过","releaseId":"term-b-neighbourhoods-v1","unitTitle":"问路小帮手","cards":[{"title":"沿着走和经过","rule":"Go along加道路表示沿着走，go past加地标表示经过。不要把past（经过）和passed（pass的过去式）混在指路词组里。现实出行先听成人安排。","example":"Go along River Road.","translation":"沿着河滨路走。"},{"title":"沿着走和经过","rule":"Go along加道路表示沿着走，go past加地标表示经过。不要把past（经过）和passed（pass的过去式）混在指路词组里。现实出行先听成人安排。","example":"Go past the red postbox.","translation":"经过红色邮筒。"},{"title":"沿着走和经过","rule":"Go along加道路表示沿着走，go past加地标表示经过。不要把past（经过）和passed（pass的过去式）混在指路词组里。现实出行先听成人安排。","example":"The gate is on your left.","translation":"大门在你的左手边。"}],"vocabulary":[{"word":"along","meaning":"沿着"},{"word":"past","meaning":"经过"},{"word":"postbox","meaning":"邮筒"},{"word":"road","meaning":"道路"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.wh","grammar.prepositions","sentence.patterns.requests"],"itemCount":9}');
INSERT INTO lessons VALUES('P4B-U03-L3',1,'term-b-neighbourhoods-v1',4,'B',3,'礼貌地问路和回答','{"id":"P4B-U03-L3","unitId":"P4B-U03","grade":4,"term":"B","unitNumber":3,"unitLesson":3,"order":11,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":12,"title":"礼貌地问路和回答","releaseId":"term-b-neighbourhoods-v1","unitTitle":"问路小帮手","cards":[{"title":"礼貌地问路和回答","rule":"问路先说Excuse me，再问Could you tell me…? 固定句框Could you tell me the way to…? 里用to。问路不一定能马上得到答案，可礼貌感谢并找可信成人帮助。","example":"Excuse me, where is the visitor centre?","translation":"打扰了，游客中心在哪里？"},{"title":"礼貌地问路和回答","rule":"问路先说Excuse me，再问Could you tell me…? 固定句框Could you tell me the way to…? 里用to。问路不一定能马上得到答案，可礼貌感谢并找可信成人帮助。","example":"Could you tell me the way to the library?","translation":"你能告诉我去图书馆的路吗？"},{"title":"礼貌地问路和回答","rule":"问路先说Excuse me，再问Could you tell me…? 固定句框Could you tell me the way to…? 里用to。问路不一定能马上得到答案，可礼貌感谢并找可信成人帮助。","example":"Thank you for your help.","translation":"谢谢你的帮助。"}],"vocabulary":[{"word":"excuse me","meaning":"打扰一下"},{"word":"way","meaning":"路线；路"},{"word":"visitor centre","meaning":"游客中心"},{"word":"help","meaning":"帮助"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.wh","grammar.prepositions","sentence.patterns.requests"],"itemCount":9}');
INSERT INTO lessons VALUES('P4B-U03-L4',1,'term-b-neighbourhoods-v1',4,'B',3,'按顺序读完路线','{"id":"P4B-U03-L4","unitId":"P4B-U03","grade":4,"term":"B","unitNumber":3,"unitLesson":4,"order":12,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":12,"title":"按顺序读完路线","releaseId":"term-b-neighbourhoods-v1","unitTitle":"问路小帮手","cards":[{"title":"按顺序读完路线","rule":"First、then、finally把路线排好。先定位起点，再依次读指令；on your left说相对行路者的左侧，不是地图永远的西边。只根据文字给出的路线回答。","example":"First, go to the blue gate.","translation":"先走到蓝色大门。"},{"title":"按顺序读完路线","rule":"First、then、finally把路线排好。先定位起点，再依次读指令；on your left说相对行路者的左侧，不是地图永远的西边。只根据文字给出的路线回答。","example":"Then turn right at the gate.","translation":"然后在大门处右转。"},{"title":"按顺序读完路线","rule":"First、then、finally把路线排好。先定位起点，再依次读指令；on your left说相对行路者的左侧，不是地图永远的西边。只根据文字给出的路线回答。","example":"Finally, stop beside the library.","translation":"最后，在图书馆旁停下。"}],"vocabulary":[{"word":"first","meaning":"首先"},{"word":"then","meaning":"然后"},{"word":"finally","meaning":"最后"},{"word":"route","meaning":"路线"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.wh","grammar.prepositions","sentence.patterns.requests"],"itemCount":9}');
INSERT INTO lessons VALUES('P5B-U03-L1',1,'term-b-neighbourhoods-v1',5,'B',3,'用because说出原因','{"id":"P5B-U03-L1","unitId":"P5B-U03","grade":5,"term":"B","unitNumber":3,"unitLesson":1,"order":9,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":12,"title":"用because说出原因","releaseId":"term-b-neighbourhoods-v1","unitTitle":"绿色行动","cards":[{"title":"用because说出原因","rule":"先说结果，再用because说明原因。We reuse paper because it saves resources。英文练习通常不用because和so同时连同一对因果分句；中文“因为……所以……”不能逐词照搬。","example":"We reuse jars because they are still useful.","translation":"我们再用罐子，因为它们还有用。"},{"title":"用because说出原因","rule":"先说结果，再用because说明原因。We reuse paper because it saves resources。英文练习通常不用because和so同时连同一对因果分句；中文“因为……所以……”不能逐词照搬。","example":"The class turns off the lights because nobody is inside.","translation":"教室里没人，所以班级关掉灯。"},{"title":"用because说出原因","rule":"先说结果，再用because说明原因。We reuse paper because it saves resources。英文练习通常不用because和so同时连同一对因果分句；中文“因为……所以……”不能逐词照搬。","example":"Because the bag is strong, Mei uses it again.","translation":"因为袋子结实，Mei再次使用它。"}],"vocabulary":[{"word":"reuse","meaning":"再次使用"},{"word":"resource","meaning":"资源"},{"word":"because","meaning":"因为"},{"word":"useful","meaning":"有用的"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.connectives","reading.inference","reading.details"],"itemCount":9}');
INSERT INTO lessons VALUES('P5B-U03-L2',1,'term-b-neighbourhoods-v1',5,'B',3,'用so连接结果','{"id":"P5B-U03-L2","unitId":"P5B-U03","grade":5,"term":"B","unitNumber":3,"unitLesson":2,"order":10,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":12,"title":"用so连接结果","releaseId":"term-b-neighbourhoods-v1","unitTitle":"绿色行动","cards":[{"title":"用so连接结果","rule":"先说原因，再用so引出结果。The tap leaks, so we tell an adult。so后面的行动应当由前面的信息支持，不把先后发生就当成因果。这里不再加because。","example":"The box is empty, so we use it for cards.","translation":"盒子空了，所以我们用它装卡片。"},{"title":"用so连接结果","rule":"先说原因，再用so引出结果。The tap leaks, so we tell an adult。so后面的行动应当由前面的信息支持，不把先后发生就当成因果。这里不再加because。","example":"The room is empty, so we switch off its lights.","translation":"房间没人，所以我们关掉灯。"},{"title":"用so连接结果","rule":"先说原因，再用so引出结果。The tap leaks, so we tell an adult。so后面的行动应当由前面的信息支持，不把先后发生就当成因果。这里不再加because。","example":"The bag has a hole, so an adult repairs it.","translation":"袋子有洞，所以成人修好它。"}],"vocabulary":[{"word":"so","meaning":"所以"},{"word":"leak","meaning":"漏水"},{"word":"repair","meaning":"修理"},{"word":"switch off","meaning":"关闭"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.connectives","reading.inference","reading.details"],"itemCount":9}');
INSERT INTO lessons VALUES('P5B-U03-L3',1,'term-b-neighbourhoods-v1',5,'B',3,'用although表达转折','{"id":"P5B-U03-L3","unitId":"P5B-U03","grade":5,"term":"B","unitNumber":3,"unitLesson":3,"order":11,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":12,"title":"用although表达转折","releaseId":"term-b-neighbourhoods-v1","unitTitle":"绿色行动","cards":[{"title":"用although表达转折","rule":"although表示虽然，引出让人意外的对比。Although the bag is old, it is strong。按本课英文句式，不同时再写but；也不要把although当成because。","example":"Although the box is old, it is useful.","translation":"虽然盒子旧了，它仍然有用。"},{"title":"用although表达转折","rule":"although表示虽然，引出让人意外的对比。Although the bag is old, it is strong。按本课英文句式，不同时再写but；也不要把although当成because。","example":"The bag is strong although it looks small.","translation":"虽然袋子看起来小，它很结实。"},{"title":"用although表达转折","rule":"although表示虽然，引出让人意外的对比。Although the bag is old, it is strong。按本课英文句式，不同时再写but；也不要把although当成because。","example":"Although it is raining, the indoor repair club is open.","translation":"虽然下雨，室内修理社团仍开放。"}],"vocabulary":[{"word":"although","meaning":"虽然"},{"word":"still","meaning":"仍然"},{"word":"strong","meaning":"结实的"},{"word":"indoor","meaning":"室内的"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.connectives","reading.inference","reading.details"],"itemCount":9}');
INSERT INTO lessons VALUES('P5B-U03-L4',1,'term-b-neighbourhoods-v1',5,'B',3,'依据记录提出行动','{"id":"P5B-U03-L4","unitId":"P5B-U03","grade":5,"term":"B","unitNumber":3,"unitLesson":4,"order":12,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":12,"title":"依据记录提出行动","releaseId":"term-b-neighbourhoods-v1","unitTitle":"绿色行动","cards":[{"title":"依据记录提出行动","rule":"先读记录，再用because解释理由或用so提出行动。比较数量要保持同一单位；发现相关现象不等于证明原因。本课只用班级虚构记录，不作真实环保统计。","example":"The tray is full, so we label a second tray.","translation":"托盘满了，所以我们给第二个托盘贴标签。"},{"title":"依据记录提出行动","rule":"先读记录，再用because解释理由或用so提出行动。比较数量要保持同一单位；发现相关现象不等于证明原因。本课只用班级虚构记录，不作真实环保统计。","example":"We reuse these folders because the covers are intact.","translation":"我们再次用这些文件夹，因为封皮完好。"},{"title":"依据记录提出行动","rule":"先读记录，再用because解释理由或用so提出行动。比较数量要保持同一单位；发现相关现象不等于证明原因。本课只用班级虚构记录，不作真实环保统计。","example":"The note does not explain every change.","translation":"便条不能解释每个变化的原因。"}],"vocabulary":[{"word":"record","meaning":"记录"},{"word":"label","meaning":"标签；贴标签"},{"word":"intact","meaning":"完好的"},{"word":"evidence","meaning":"依据"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.connectives","reading.inference","reading.details"],"itemCount":9}');
INSERT INTO lessons VALUES('P6B-U03-L1',1,'term-b-neighbourhoods-v1',6,'B',3,'时间表不等于耗时','{"id":"P6B-U03-L1","unitId":"P6B-U03","grade":6,"term":"B","unitNumber":3,"unitLesson":1,"order":9,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":12,"title":"时间表不等于耗时","conceptLabIds":["tense.future"],"releaseId":"term-b-neighbourhoods-v1","unitTitle":"规划精彩旅程","cards":[{"title":"时间表不等于耗时","rule":"规划行程先分清出发时刻、到达时刻与经过时长。虚构表格里10:20到10:50是30分钟。写将来计划可用will加动词原形；不要再加第三人称s。","example":"The group will leave at 09:10.","translation":"小组将于9点10分出发。"},{"title":"时间表不等于耗时","rule":"规划行程先分清出发时刻、到达时刻与经过时长。虚构表格里10:20到10:50是30分钟。写将来计划可用will加动词原形；不要再加第三人称s。","example":"The journey will take twenty minutes.","translation":"这段路程将耗时20分钟。"},{"title":"时间表不等于耗时","rule":"规划行程先分清出发时刻、到达时刻与经过时长。虚构表格里10:20到10:50是30分钟。写将来计划可用will加动词原形；不要再加第三人称s。","example":"They will arrive before the show.","translation":"他们将于演出前到达。"}],"vocabulary":[{"word":"depart","meaning":"出发"},{"word":"arrive","meaning":"到达"},{"word":"duration","meaning":"时长"},{"word":"timetable","meaning":"时间表"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.future","sentence.patterns.connections","reading.integrating"],"itemCount":9}');
INSERT INTO lessons VALUES('P6B-U03-L2',1,'term-b-neighbourhoods-v1',6,'B',3,'把预算算清楚','{"id":"P6B-U03-L2","unitId":"P6B-U03","grade":6,"term":"B","unitNumber":3,"unitLesson":2,"order":10,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":12,"title":"把预算算清楚","releaseId":"term-b-neighbourhoods-v1","unitTitle":"规划精彩旅程","cards":[{"title":"把预算算清楚","rule":"读预算时分清每人费用和整组总额，先相乘再相加。虚构价格只供本课算读练习。should加动词原形提出建议；建议不是必须，也不保证实际价格。","example":"We should check the cost per person.","translation":"我们应当核对每人的费用。"},{"title":"把预算算清楚","rule":"读预算时分清每人费用和整组总额，先相乘再相加。虚构价格只供本课算读练习。should加动词原形提出建议；建议不是必须，也不保证实际价格。","example":"Four tickets at five dollars each cost twenty dollars.","translation":"四张票每张5元，共20元。"},{"title":"把预算算清楚","rule":"读预算时分清每人费用和整组总额，先相乘再相加。虚构价格只供本课算读练习。should加动词原形提出建议；建议不是必须，也不保证实际价格。","example":"We should keep some money for water.","translation":"我们应当留些钱买水。"}],"vocabulary":[{"word":"budget","meaning":"预算"},{"word":"per person","meaning":"每人"},{"word":"total","meaning":"总额"},{"word":"dollar","meaning":"元（本课虚构计价单位）"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.future","sentence.patterns.connections","reading.integrating"],"itemCount":9}');
INSERT INTO lessons VALUES('P6B-U03-L3',1,'term-b-neighbourhoods-v1',6,'B',3,'给行程准备备选方案','{"id":"P6B-U03-L3","unitId":"P6B-U03","grade":6,"term":"B","unitNumber":3,"unitLesson":3,"order":11,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":12,"title":"给行程准备备选方案","conceptLabIds":["tense.future"],"releaseId":"term-b-neighbourhoods-v1","unitTitle":"规划精彩旅程","cards":[{"title":"给行程准备备选方案","rule":"谈将来可能发生的条件，常用If加一般现在时，主句用will加原形。If it rains, we will visit the indoor hall。不因为说未来就把if从句也写will。","example":"If it rains, we will visit the indoor hall.","translation":"如果下雨，我们将参观室内展厅。"},{"title":"给行程准备备选方案","rule":"谈将来可能发生的条件，常用If加一般现在时，主句用will加原形。If it rains, we will visit the indoor hall。不因为说未来就把if从句也写will。","example":"If the bus is full, we will wait with our adult.","translation":"如果公交车满了，我们会和成人一起等。"},{"title":"给行程准备备选方案","rule":"谈将来可能发生的条件，常用If加一般现在时，主句用will加原形。If it rains, we will visit the indoor hall。不因为说未来就把if从句也写will。","example":"We will take a break if we feel tired.","translation":"如果累了，我们将休息。"}],"vocabulary":[{"word":"backup plan","meaning":"备选方案"},{"word":"indoor hall","meaning":"室内展厅"},{"word":"condition","meaning":"条件"},{"word":"wait","meaning":"等候"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.future","sentence.patterns.connections","reading.integrating"],"itemCount":9}');
INSERT INTO lessons VALUES('P6B-U03-L4',1,'term-b-neighbourhoods-v1',6,'B',3,'综合时间费用作决定','{"id":"P6B-U03-L4","unitId":"P6B-U03","grade":6,"term":"B","unitNumber":3,"unitLesson":4,"order":12,"subtitle":"下学期第三站：看位置、读路线，依据资料安排小行动","minutes":12,"title":"综合时间费用作决定","releaseId":"term-b-neighbourhoods-v1","unitTitle":"规划精彩旅程","cards":[{"title":"综合时间费用作决定","rule":"比较两个方案要同时核对时间、费用与条件，不能只看最便宜。根据明确的要求排除不合适方案；could加原形表示可考虑的选择，不把建议写成确定结果。","example":"We could choose the earlier bus.","translation":"我们可以考虑较早的那班公交车。"},{"title":"综合时间费用作决定","rule":"比较两个方案要同时核对时间、费用与条件，不能只看最便宜。根据明确的要求排除不合适方案；could加原形表示可考虑的选择，不把建议写成确定结果。","example":"The cheaper plan arrives too late.","translation":"较便宜的方案到达得太晚。"},{"title":"综合时间费用作决定","rule":"比较两个方案要同时核对时间、费用与条件，不能只看最便宜。根据明确的要求排除不合适方案；could加原形表示可考虑的选择，不把建议写成确定结果。","example":"We will check the opening time before deciding.","translation":"决定前我们会核对开放时间。"}],"vocabulary":[{"word":"option","meaning":"选项；方案"},{"word":"deadline","meaning":"截止时间"},{"word":"afford","meaning":"负担得起"},{"word":"decide","meaning":"决定"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.future","sentence.patterns.connections","reading.integrating"],"itemCount":9}');
